/**
 * 突脸数字的状态与流程：画布调度、播放、参数、导入导出。
 *
 * 从 signalNumber.vue 里拆出来，模板只负责排版与双向绑定；这里不含样式，也不认识 .sn-* 类名。
 */
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import {
  ASPECTS,
  exportSettings,
  importSettings,
  moveOption,
  previewIssue,
} from './bilitoy/editor-data.js'
import { APP_CONFIG, validateOptions } from './bilitoy/config.js'
import { exportFileName } from '../../../utils/exportName.js'
import { DESIGN_GROUPS, DEFAULT_DESIGN, validateDesign } from './bilitoy/design.js'
import { DEFAULT_SETTINGS, DESIGN_STORAGE_KEY } from './bilitoy/default-settings.js'
import { HEIGHT, WIDTH, SignalRenderer, getPhase } from './bilitoy/engine.js'
import { exportFrameZip } from './bilitoy/frame-export.js'
import { exportGif } from './bilitoy/gif-export.js'
import { DEFAULT_GIF_PROFILE, GIF_PROFILES, GIF_SIZES, gifSettings } from './bilitoy/gif-options.js'

// 选项卡与设计参数各存一份，键名沿用上游，避免和站内其它页面串档
const OPTIONS_STORAGE_KEY = 'dt-signal-options'

const VIEW_ITEMS = [
  { value: 'grid', label: '同屏' },
  { value: 'single', label: '单画面' },
]
const ASPECT_ITEMS = Object.keys(ASPECTS).map(value => ({ value, label: value }))
const FORMAT_ITEMS = [
  { value: 'gif', label: 'GIF' },
  { value: 'zip', label: 'PNG 帧序列' },
]


export function useSignalStage() {
    const duration = APP_CONFIG.duration
    const stillTime = APP_CONFIG.stillTime
    const maxOptions = APP_CONFIG.maxOptions

    const design = reactive({ ...DEFAULT_DESIGN })
    const options = ref(DEFAULT_SETTINGS.options.map(option => ({ ...option })))
    const preview = DEFAULT_SETTINGS.preview
    const view = ref(preview.view)
    const aspect = ref(preview.aspect)
    const selectedId = ref(preview.selectedId)

    const time = ref(stillTime)
    const playing = ref(false)
    // 音轨跟着时间轴走：播放时以 audio.currentTime 为准，浏览器拒绝自动播放就自动回落到计时器
    const sound = ref(true)
    // 音轨能不能播（被浏览器拦下或解码失败后置 false，按钮随即变灰）
    const audioAvailable = ref(true)

    const exportFormat = ref('gif')
    const exportStart = ref(0)
    const exportEnd = ref(Number(duration.toFixed(2)))
    const exportFps = ref(12)
    const gifProfile = ref(DEFAULT_GIF_PROFILE)
    const gifSize = ref('360p')

    // 换压缩档时把尺寸带到该档的自然值（增强 / 无损 给原生 1080p）
    watch(gifProfile, profile => {
      const preset = GIF_PROFILES[profile]
      if (preset && GIF_SIZES[preset.size]) gifSize.value = preset.size
    })
    const exporting = ref(false)
    const progress = ref(0)

    const note = ref('')
    const optionError = ref('')
    const designNote = ref('')
    const curveOk = ref(true)
    const issue = ref('')

    const canvasRef = ref(null)
    const stageRef = ref(null)
    const importRef = ref(null)
    const audioRef = ref(null)
    // 3 MB 的原声 wav 放在 public 里，不走 webpack
    const audioSrc = '/assets/part/signal-audio.wav'
    const windowStyle = reactive({ width: '0px', height: '0px' })

    let renderer = null
    let raf = 0
    let timeStart = 0
    let clockStart = 0
    let cancelled = false
    let designFrame = 0
    let resizeObserver = null
    let noteTimer = 0

    const selectedLabel = computed(() => {
      const hit = options.value.find(option => option.id === selectedId.value)
      return hit ? `${hit.label} ${hit.value}` : '—'
    })

    // GIF 参数按「压缩档 + 尺寸」现算，档位里没写 height 时回落到尺寸表
    const gifCurrent = computed(() => {
      const profile = GIF_PROFILES[gifProfile.value] || GIF_PROFILES[DEFAULT_GIF_PROFILE]
      let height = GIF_SIZES[gifSize.value] ?? GIF_SIZES['360p']
      try {
        height = gifSettings(gifProfile.value, gifSize.value).height
      } catch {
        // 参数越界就用上面的回落值
      }
      return { ...profile, height }
    })

    const phase = ref(getPhase(stillTime, design, 2))

    // 数字位数决定滚动就位的时长，取所有选项里最长的那个
    function digitCount() {
      const digits = options.value.map(option => String(option.value).length)
      return Math.max(1, Math.min(APP_CONFIG.maxDigits, ...digits))
    }

    // 提示条几秒后自动消失，避免一直占位
    function notify(message) {
      note.value = message
      clearTimeout(noteTimer)
      if (message) noteTimer = setTimeout(() => { note.value = '' }, 4000)
    }

    function draw() {
      if (!renderer || issue.value) return
      renderer.render(time.value, options.value, view.value, selectedId.value)
      phase.value = getPhase(time.value, design, digitCount())
    }

    // 滑杆连续触发时每帧只提交一次，重建设计层比较费时
    function scheduleDesign() {
      if (designFrame) return
      designFrame = requestAnimationFrame(() => {
        designFrame = 0
        if (!renderer) return
        try {
          renderer.setDesign({ ...design })
          curveOk.value = renderer.curvatureSupported
        } catch (e) {
          designNote.value = e.message
        }
        issue.value = previewIssue(design)
        draw()
      })
    }

    // 画面按可用空间等比缩放；4:3 时靠 object-fit 居中裁切
    function layoutWindow() {
      const box = stageRef.value
      if (!box) return
      const ratio = aspect.value === '4:3' ? 4 / 3 : 16 / 9
      const availableWidth = box.clientWidth
      const availableHeight = box.clientHeight
      if (!availableWidth || !availableHeight) return
      let width = availableWidth
      let height = width / ratio
      if (height > availableHeight) {
        height = availableHeight
        width = height * ratio
      }
      windowStyle.width = `${Math.floor(width)}px`
      windowStyle.height = `${Math.floor(height)}px`
    }

    function normalizeSelection() {
      if (!options.value.some(option => option.id === selectedId.value)) {
        selectedId.value = options.value[0]?.id ?? ''
      }
    }

    function persist() {
      try {
        localStorage.setItem(DESIGN_STORAGE_KEY, JSON.stringify(design))
        localStorage.setItem(OPTIONS_STORAGE_KEY, JSON.stringify(options.value))
      } catch {
        // 隐私模式下写不进去，忽略即可
      }
    }

    function restore() {
      try {
        const stored = localStorage.getItem(DESIGN_STORAGE_KEY)
        if (stored) Object.assign(design, validateDesign(JSON.parse(stored)))
      } catch {
        // 存档坏了就用默认值
      }
      try {
        const stored = localStorage.getItem(OPTIONS_STORAGE_KEY)
        if (stored) options.value = validateOptions(JSON.parse(stored))
      } catch {
        // 同上
      }
      normalizeSelection()
    }

    function setField(field, value) {
      try {
        Object.assign(design, validateDesign({ [field.key]: value }, design))
        designNote.value = ''
        issue.value = previewIssue(design)
        scheduleDesign()
      } catch (e) {
        designNote.value = e.message
      }
    }

    function resetDesign() {
      Object.assign(design, DEFAULT_DESIGN)
      designNote.value = ''
      issue.value = previewIssue(design)
      scheduleDesign()
    }

    function commitOptions(next) {
      try {
        options.value = validateOptions(next)
        optionError.value = ''
        normalizeSelection()
      } catch (e) {
        optionError.value = e.message
      }
    }

    function editOption(index, key, value) {
      commitOptions(options.value.map((option, i) => (i === index ? { ...option, [key]: String(value) } : option)))
    }

    function shiftOption(index, direction) {
      try {
        options.value = moveOption(options.value, options.value[index].id, direction)
        optionError.value = ''
      } catch (e) {
        optionError.value = e.message
      }
    }

    function dropOption(index) {
      if (options.value.length <= 1) return
      commitOptions(options.value.filter((option, i) => i !== index))
    }

    function addOption() {
      if (options.value.length >= maxOptions) return
      const taken = new Set(options.value.map(option => option.label))
      let label = 'NEW'
      for (let n = 1; taken.has(label); n += 1) label = `NEW${n}`
      commitOptions([
        ...options.value,
        { id: `opt-${Date.now()}-${options.value.length}`, label, value: '0' },
      ])
    }

    function resetOptions() {
      commitOptions(DEFAULT_SETTINGS.options.map(option => ({ ...option })))
      selectedId.value = preview.selectedId
    }

    function downloadSettings() {
      try {
        const text = exportSettings({
          options: options.value,
          design,
          view: view.value,
          selectedId: selectedId.value,
          aspect: aspect.value,
        })
        saveBlob(new Blob([text], { type: 'application/json' }), exportFileName('突脸数字', ['配置'], 'json'))
        notify('已导出配置。')
      } catch (e) {
        notify(e.message)
      }
    }

    function pickImport() {
      importRef.value?.click()
    }

    function onImport(event) {
      const file = event.target.files?.[0]
      event.target.value = ''
      if (!file) return
      const reader = new FileReader()
      reader.onload = () => {
        try {
          const loaded = importSettings(String(reader.result), {
            design,
            view: view.value,
            aspect: aspect.value,
            selectedId: selectedId.value,
          })
          options.value = loaded.options
          Object.assign(design, loaded.design)
          view.value = loaded.view
          aspect.value = loaded.aspect
          selectedId.value = loaded.selectedId
          issue.value = previewIssue(design)
          scheduleDesign()
          notify('已导入配置。')
        } catch (e) {
          notify(e.message)
        }
      }
      reader.onerror = () => notify('读取文件失败。')
      reader.readAsText(file)
    }

    function tick(now) {
      if (!playing.value) return
      const el = audioRef.value
      // 音轨能放就以 audio.currentTime 为准：掉帧时音频时钟不会漂，画面跟着声音走
      const fromAudio = sound.value && el && !el.paused && !el.seeking
      const current = fromAudio ? el.currentTime : timeStart + (now - clockStart) / 1000
      if (current >= duration) {
        time.value = duration
        draw()
        stop()
        return
      }
      time.value = current
      draw()
      raf = requestAnimationFrame(tick)
    }

    function stop() {
      playing.value = false
      cancelAnimationFrame(raf)
      raf = 0
      audioRef.value?.pause()
    }

    // 从当前时间点起播音轨；被浏览器拦下（没交互 / 解码失败）就关掉音频，画面照常
    function startAudio() {
      const el = audioRef.value
      if (!sound.value || !el) return
      el.currentTime = Math.min(time.value, duration)
      const played = el.play()
      if (played && typeof played.catch === 'function') {
        played.catch(() => {
          sound.value = false
          audioAvailable.value = false
          notify('音频暂时无法播放，画面仍可预览。')
        })
      }
    }

    function play() {
      if (playing.value) return
      if (time.value >= duration - 1e-3) time.value = 0
      timeStart = time.value
      clockStart = performance.now()
      playing.value = true
      startAudio()
      raf = requestAnimationFrame(tick)
    }

    function setSound(value) {
      sound.value = value
      if (!audioRef.value) return
      if (!value) {
        audioRef.value.pause()
      } else if (playing.value) {
        startAudio()
      }
    }

    function togglePlay() {
      if (playing.value) stop()
      else play()
    }

    function restart() {
      stop()
      time.value = 0
      if (audioRef.value) audioRef.value.currentTime = 0
      draw()
    }

    function seek(value) {
      stop()
      time.value = Math.max(0, Math.min(duration, Number(value) || 0))
      if (audioRef.value) audioRef.value.currentTime = time.value
      draw()
    }

    function onKeydown(event) {
      const tag = event.target?.tagName
      if (tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA') return
      if (event.code === 'Space') {
        event.preventDefault()
        togglePlay()
      } else if (event.code === 'ArrowLeft') {
        event.preventDefault()
        seek(time.value - 1 / 30)
      } else if (event.code === 'ArrowRight') {
        event.preventDefault()
        seek(time.value + 1 / 30)
      }
    }

    function saveBlob(blob, filename) {
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename
      document.body.appendChild(link)
      link.click()
      link.remove()
      setTimeout(() => URL.revokeObjectURL(url), 1000)
    }

    // 当前帧按画幅裁切后另存，尺寸和导出时一致
    function saveStill() {
      draw()
      const source = canvasRef.value
      const target = document.createElement('canvas')
      const context = target.getContext('2d')
      if (aspect.value === '4:3') {
        target.width = ASPECTS['4:3'].width
        target.height = ASPECTS['4:3'].height
        context.drawImage(source, 240, 0, 1440, 1080, 0, 0, target.width, target.height)
      } else {
        target.width = ASPECTS['16:9'].width
        target.height = ASPECTS['16:9'].height
        context.drawImage(source, 0, 0)
      }
      target.toBlob(blob => {
        if (blob) saveBlob(blob, exportFileName('突脸数字', ['静帧', aspect.value === '4:3' ? '4x3' : '16x9'], 'png'))
      }, 'image/png')
    }

    function exportRange() {
      const start = Math.max(0, Math.min(Number(exportStart.value) || 0, duration))
      const end = Math.max(0, Math.min(Number(exportEnd.value) || 0, duration))
      return { start: Math.min(start, end), end: Math.max(start, end) }
    }

    async function startExport() {
      if (exporting.value || issue.value) return
      const { start, end } = exportRange()
      if (end - start < 0.2) {
        notify('时间范围至少要 0.2 秒。')
        return
      }
      stop()
      exporting.value = true
      cancelled = false
      progress.value = 0
      notify('')
      const base = {
        options: options.value,
        design: { ...design },
        view: view.value,
        selectedId: selectedId.value,
        aspect: aspect.value,
        start,
        end,
        onProgress: (done, total) => {
          progress.value = total ? Math.min(100, (done / total) * 100) : 0
        },
        isCancelled: () => cancelled,
      }
      try {
        if (exportFormat.value === 'zip') {
          const fps = Math.max(1, Math.min(30, Math.round(Number(exportFps.value)) || 12))
          const result = await exportFrameZip({ ...base, fps })
          if (!result) {
            notify('已取消导出。')
          } else {
            saveBlob(result.blob, exportFileName('突脸数字', ['帧序列', `${fps}fps`], 'zip'))
            notify(`已导出 ${result.frameCount} 帧 PNG。`)
          }
        } else {
          const result = await exportGif({
            ...base,
            size: gifSize.value,
            compression: gifProfile.value,
          })
          if (!result) {
            notify('已取消导出。')
          } else {
            saveBlob(result.blob, exportFileName('突脸数字', [gifCurrent.value.label, gifCurrent.value.size], 'gif'))
            notify(`已导出 GIF：${result.width} × ${result.height}，${result.frameCount} 帧。`)
          }
        }
      } catch (e) {
        notify(e.message || '导出失败。')
      } finally {
        exporting.value = false
      }
    }

    function cancelExport() {
      cancelled = true
    }

    // 字体没下完就渲染会把字形缓存成系统字体，所以先等 Saira 就绪
    async function ensureFonts() {
      if (!document.fonts) return
      try {
        await Promise.all([
          document.fonts.load(`900 ${WIDTH / 4}px Saira`),
          document.fonts.load(`400 ${WIDTH / 4}px Saira`),
        ])
        await document.fonts.ready
      } catch {
        // 字体加载失败就用系统字体
      }
    }

    onMounted(async () => {
      restore()
      issue.value = previewIssue(design)
      layoutWindow()
      resizeObserver = new ResizeObserver(layoutWindow)
      if (stageRef.value) resizeObserver.observe(stageRef.value)
      window.addEventListener('keydown', onKeydown)
      await ensureFonts()
      if (!canvasRef.value) return
      renderer = new SignalRenderer(canvasRef.value)
      curveOk.value = renderer.curvatureSupported
      try {
        renderer.setDesign({ ...design })
      } catch (e) {
        designNote.value = e.message
      }
      draw()
    })

    onBeforeUnmount(() => {
      stop()
      cancelAnimationFrame(designFrame)
      resizeObserver?.disconnect()
      window.removeEventListener('keydown', onKeydown)
      clearTimeout(noteTimer)
    })

    watch([options, view, selectedId], () => {
      normalizeSelection()
      draw()
      persist()
    }, { deep: true })

    watch(design, () => {
      scheduleDesign()
      persist()
    }, { deep: true })

    watch(aspect, () => {
      layoutWindow()
      persist()
    })

    return {
      ASPECTS,
      ASPECT_ITEMS,
      DESIGN_GROUPS,
      FORMAT_ITEMS,
      GIF_PROFILES,
      GIF_SIZES,
      HEIGHT,
      VIEW_ITEMS,
      WIDTH,
      addOption,
      aspect,
      audioRef,
      audioSrc,
      cancelExport,
      canvasRef,
      curveOk,
      design,
      designNote,
      downloadSettings,
      dropOption,
      duration,
      editOption,
      exportEnd,
      exportFormat,
      exportFps,
      exportStart,
      exporting,
      gifCurrent,
      gifProfile,
      gifSize,
      audioAvailable,
      importRef,
      issue,
      maxOptions,
      note,
      onImport,
      optionError,
      options,
      phase,
      pickImport,
      playing,
      progress,
      resetDesign,
      resetOptions,
      restart,
      saveStill,
      seek,
      selectedId,
      selectedLabel,
      setField,
      sound,
      setSound,
      shiftOption,
      stageRef,
      startExport,
      stillTime,
      time,
      togglePlay,
      view,
      windowStyle,
    }
}
